import cv2import matplotlib.pyplot as pltfrom PIL import Imageimport matplotlib.cm as cmimport numpy as np# =========================# Task 2: Loading Images# =========================# Load image using OpenCVimg = cv2.imread('Image/cameraman.tif')plt.imshow(img)plt.show()# Load image using PILimg2 = Image.open('Image/lena_gray_256.tif')plt.imshow(img2, cmap=cm.Greys_r)plt.show()# =========================# Task 3: Image Storing# =========================# Save using OpenCVcv2.imwrite('new_image.jpg', img)# Save using PILimg2.convert('RGB').save('new_image2.jpg')# =========================# Task 4: Display as Array# =========================print("OpenCV image shape:")print(img.shape)print("OpenCV image array:")print(img)# Convert PIL image to NumPy arrayimg_array = np.array(img2)print("PIL image shape:")print(img_array.shape)print("PIL image array:")print(img_array)# =========================# NumPy Exercises# =========================# 10 zeroszeros_array = np.zeros(10)print(zeros_array)# 10 onesones_array = np.ones(10)print(ones_array)# 10 fivesfives_array = np.ones(10) * 5print(fives_array)# Integers from 10 to 50numbers = np.arange(10, 51)print(numbers)# Even integers from 10 to 50even_numbers = np.arange(10, 51, 2)print(even_numbers)# 3x3 matrix from 0 to 8matrix = np.arange(9).reshape(3, 3)print(matrix)# 3x3 identity matrixidentity_matrix = np.eye(3)print(identity_matrix)# Random number between 0 and 1random_number = np.random.rand(1)print(random_number)# 25 random numbersrandom_array = np.random.randn(25)print(random_array)# 20 linearly spaced points from 0 to 1linear_points = np.linspace(0, 1, 20)print(linear_points)# =========================# NumPy Indexing# =========================arr_2d = np.array([    [5, 10, 15],    [20, 25, 30],    [35, 40, 45]], np.uint8)print(arr_2d)# Retrieve 25print(arr_2d[1, 1])# Second rowprint(arr_2d[1, :])# Third columnprint(arr_2d[:, 2])# Bottom-right 2x2print(arr_2d[1:, 1:])